#mysteries{位置：相對；溢出：隱藏}
    #mysteries .wrap{位置：相對；z-index：3}
    .myst-filterbar{顯示：flex；flex-wrap：wrap；間隙：20px 28px；align-items：flex-end；margin-bottom：14px}
    .myst-filter-group{顯示：flex;flex-direction:column;gap:9px;min-width:0}
    .myst-filter-label{font-family:"空格單色",ui-monospace,monospace;font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:#d3a8c2}
    .myst-chip-row{顯示：flex;flex-wrap:wrap;間隙：8px}
    .myst-晶片{
      顯示：inline-flex；對齊項目：中心；間隙：8px；遊標：指針；
      內邊距：9px 15px；邊框半徑：999px；
      font-family:"空格單色",ui-monospace,monospace;font-size:11px;
      字母間距：.14em；文字轉換：大寫；顏色：#f4e3d7；
      背景:rgba(20,7,44,.72);邊框:1px實心rgba(255,45,124,.3);
      過渡：變換 .15s 緩動，box-shadow .2s 緩動，邊框顏色 .2s 緩動；
    }
    .myst-chip:hover{變換:translateY(-1px);邊框顏色:rgba(255,45,124,.65);box-shadow:0 0 20px rgba(255,45,124,.25)}
    .myst-chip.active{
      背景：var(--vi-grad-sunset,線性漸層(90deg,#ff2d7c,#ff8a3d 52%,#ffd166));
      顏色:var(--vi-ink,#33051c);邊框顏色:透明;字型粗細:700;
      盒子陰影：0 8px 22px -8px rgba(255,45,124,.65);
    }
    .myst-chip .myst-dot{寬度:8px;高度:8px;邊框半徑:99px;flex:0 0 自動}
    .myst-chip.active .myst-dot{輪廓:1px實心rgba(51,5,28,.4)}
    .myst-dot--resolved{背景:線性漸變(135deg,var(--vi-gold,#ffd166),#7ee08c)}
    .myst-dot--open{背景:var(--vi-pink,#ff2d7c);box-shadow:0 0 10px rgba(255,45,124,.8)}
    .myst-dot--lenda{背景:var(--vi-purple,#7b2ff7);box-shadow:0 0 10px rgba(123,47,247,.8)}
    .myst-dot--all{背景:#f4e3d7}
    .myst-chip 小{
      字體大小：10px；填滿：2px 7px；邊框半徑：99px；字母間距：.08em；
      背景:rgba(11,13,42,.55);顏色:繼承;邊框:1px實心rgba(255,255,255,.18);
    }
    .myst-chip.active 小{背景:rgba(51,5,28,.22);邊框顏色:rgba(51,5,28,.3)}
    .myst-選擇{
      外觀：無；-webkit-外觀：無；遊標：指針；最小寬度：220px；
      內邊距：10px 38px 10px 14px；邊框半徑：10px；
      font-family:"空格單色",ui-monospace,monospace;font-size:12px;letter-spacing:.06em;
      顏色:#fff5ec;背景:rgba(20,7,44,.72);邊框:1px實心rgba(255,45,124,.3);
      背景圖像：url（“數據：圖像/ svg + xml;utf8，<svg xmlns ='http://www.w3.org/2000/svg'寬度='12'高度='8'viewBox ='0 0 12 8'><路徑d ='M1 1l5 5 5-5'填充='無'筆畫='%23ff2d7c'筆畫寬度='2'筆畫-linecap='round'/></svg>");
      背景重複：無重複；背景位置：右14px中心；
    }
    .myst-select:焦點{輪廓:無;邊框顏色:rgba(255,45,124,.7);box-shadow:0 0 18px rgba(255,45,124,.3)}
    .myst-選擇選項{背景:#0b0d2a;顏色:#fff5ec}
    .myst-狀態-desc{
      邊距：0 0 18px；最大寬度：760px；顏色：#d9c3d2；字體大小：14px；行高：1.6；
      左框：3px 實心 rgba(255,45,124,.55);左填充：14px;
    }
    .myst-grid{顯示：網格；網格模板列：重複（自動填充，minmax（330px，1fr））；間隙：18px；對齊項目：開始}
    .myst-card{顯示：flex；flex-方向：列；間隙：0；填充：22px 22px 18px}
    .myst-card-top{顯示：flex;align-items:center;justify-content:space- Between;gap:10px;flex-wrap:wrap;margin-bottom:14px}
    .myst-file-no{font-family:"空格 Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.22em;color:#b98ca9;text-transform:uppercase}
    .myst-stamp{變換：旋轉（-2deg）;字體大小：10px;字母間距：.2em;填充：6px 13px}
    .myst-stamp--已解{
      背景：線性漸變（90deg，var（--vi-gold，#ffd166），#7ee08c）；
      顏色:var(--vi-ink,#33051c);盒子陰影:0 8px 22px -8px rgba(255,209,102,.7),0 0 20px rgba(126,224,140,.25);
    }
    .myst-stamp--open{顏色:var(--vi-pink,#ff2d7c);box-shadow:0 0 22px rgba(255,45,124,.4)}
    .myst-stamp--圖例{
      顏色:#cfa9ff;盒子陰影:0 0 22px rgba(123,47,247,.45);
      背景：
        線性漸變(rgba(26,9,54,.9),rgba(26,9,54,.9)) 填滿框，
        線性漸變（90deg，var（--vi-purple，#7b2ff7），var（--vi-pink-2，#f152ff））邊框；
    }
    .myst-遊戲晶片{
      顯示：inline-flex；對齊項目：中心；間隙：6px；邊距底部：10px；
      font-family:"空格單色",ui-monospace,monospace;font-size:10px;
      字母間距：.18em；文字轉換：大寫；顏色：var(--vi-gold,#ffd166);
    }
    .myst-game-chip::before{內容：""；寬度：14px；高度：1px；背景：var(--vi-gold，#ffd166)；不透明度：.7}
    .myst-card h3{邊距:0 0 10px;字體大小:20px;行高:1.25;顏色:#fff5ec}
    .myst-desc{邊距:0;顏色:#d9c8d4;字體大小:14px;行高:1.62}
    .myst-toggle{margin-top:16px;align-self:flex-start}
    .myst-body{margin-top:16px;padding-top:16px;border-top:1px 虛線 rgba(255,45,124,.35)}
    .myst-證據-標籤{
      顯示：flex；對齊項目：中心；間隙：8px；邊距：16px 0 4px；
      font-family:"空格單色",ui-monospace,monospace;font-size:10px;
      字母間距：.26em；文字轉換：大寫；顏色：#ff9ec4；
    }
    .myst-evidence-label:first-child{margin-top:0}
    .myst-evidence-label::after{內容:"";flex:1;高度:1px;背景:rgba(255,45,124,.25)}
    .myst-list{列表樣式：無；邊距：8px 0 0；填入：0}
    .myst-list li{顯示：flex；間隙：10px；對齊項目：基線；邊距底部：8px；顏色：#e6d6dd；字體大小：13.5px；行高：1.6}
    .myst-idx{
      flex:0 0 auto;font-family:"空格單色",ui-monospace,monospace;font-size:10px;
      字母間距:.08em;顏色:var(--vi-gold,#ffd166);不透明度:.85;最小寬度:30px;
    }
    .myst-決議{
      上邊距：18px；內邊距：14px 16px；邊框半徑：10px；
      邊框:1px 虛線 rgba(255,209,102,.6);背景:rgba(255,209,102,.07);
    }
    .myst-resolution .myst-evidence-label{顏色:var(--vi-gold,#ffd166);margin-top:0}
    .myst-resolution .myst-evidence-label::after{背景:rgba(255,209,102,.35)}
    .myst-解析度 p{邊距:8px 0 0;顏色:#ffe9bd;字體大小:13.5px;行高:1.62}
    .myst-哪裡{
      顯示：flex；間隙：10px；對齊項目：基線；邊距頂部：16px；
      font-family:"空格單色",ui-monospace,monospace;font-size:12px;
      顏色：#cdb4c6；行高：1.55；
    }
    .myst-where svg{flex:0 0 auto;寬度:14px;高度:14px;變換:translateY(2px);顏色:var(--vi-pink,#ff2d7c)}
    .myst-空{
      填充：34px 26px；文字對齊：居中；顏色：#d3a8c2；
      font-family:"Space Mono",ui-monospace,monospace;font-size:13px;letter-spacing:.08em;
    }
    @media（最大寬度：760px）{
      .myst-filterbar{flex-direction:column;align-items:stretch}
      .myst-選擇{寬度：100%}
      .myst-grid{網格模板列:1fr}
      .myst-card{填充：18px 16px 16px}
    }
    @media（首選減少運動：減少）{
      .myst-chip,.myst-chip:hover{變換:無;過渡:無}
    }
